const rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value),escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char])),params=new URLSearchParams(location.search),id=params.get('order')||localStorage.getItem('ruangrupa-current-order'),orders=JSON.parse(localStorage.getItem('ruangrupa-orders')||'[]'),localOrder=orders.find(order=>order.id===id),accessToken=params.get('token')||localOrder?.paymentToken,content=document.querySelector('#content');
const paymentLabels={pending:'Menunggu pembayaran',paid:'Pembayaran berhasil',failed:'Pembayaran gagal',expired:'Kedaluwarsa',cancelled:'Dibatalkan',refunded:'Dikembalikan'},shippingLabels={waiting:'Menunggu diproses',preparing:'Sedang disiapkan',shipped:'Sedang dikirim',completed:'Pesanan selesai'};
const formatDate=value=>value?new Date(value.endsWith?.('Z')?value:`${value}Z`).toLocaleString('id-ID'):'—';
function timeline(order,payment){const level={waiting:0,preparing:1,shipped:2,completed:3}[order.fulfillmentStatus]??0,steps=[['Pesanan dibuat',formatDate(order.createdAt)],['Sedang disiapkan',level>=1?'Pesanan sedang disiapkan oleh toko':'Menunggu pembayaran dan penyiapan'],['Dikirim',level>=2?`${formatDate(order.shippedAt)}${order.trackingNumber?` · ${order.trackingNumber}`:''}`:'Belum dikirim'],['Selesai',level>=3?formatDate(order.completedAt):'Belum selesai']];return `<div class="timeline">${steps.map((step,index)=>`<div class="step ${index<=level?'done':''}"><div class="marker"><span class="dot"></span><span class="line"></span></div><div><strong>${step[0]}</strong><small>${escapeHtml(step[1])}</small></div></div>`).join('')}</div>`}
function render(data){const{order,items,payment}=data,paymentGood=payment?.status==='paid',shippingDone=order.fulfillmentStatus==='completed';content.innerHTML=`<div class="grid"><section class="card"><div class="status-card"><div class="status-box"><small>Pembayaran</small><span class="pill ${paymentGood?'good':''}">${escapeHtml(paymentLabels[payment?.status]||'Belum tersedia')}</span><div class="muted" style="margin-top:7px">${escapeHtml(payment?.method||'Metode belum dipilih')}</div></div><div class="status-box"><small>Pengiriman</small><span class="pill ${shippingDone?'good':''}">${escapeHtml(shippingLabels[order.fulfillmentStatus]||'Menunggu diproses')}</span><div class="muted" style="margin-top:7px">Tujuan: ${escapeHtml(order.shippingCity)}</div></div></div>${order.trackingNumber?`<div class="tracking"><small>Nomor resi</small><br><strong>${escapeHtml(order.trackingNumber)}</strong></div>`:''}<h2>Perjalanan pesanan</h2>${timeline(order,payment)}</section><aside class="card"><p class="muted" style="margin:0">Nomor pesanan</p><h2 style="margin-top:3px">${escapeHtml(order.id)}</h2><div class="items">${items.map(item=>`<div class="item"><span><strong>${escapeHtml(item.productName)}</strong>${item.colorName?`<small>Warna: ${escapeHtml(item.colorName)}</small>`:''}<small>${item.quantity} × ${rupiah(item.unitPrice)}</small></span><strong>${rupiah(item.lineTotal)}</strong></div>`).join('')}</div><div class="totals"><div class="total-row"><span>Subtotal</span><strong>${rupiah(order.subtotal)}</strong></div><div class="total-row"><span>Pengiriman</span><strong>${rupiah(order.shipping)}</strong></div><div class="total-row"><span>Diskon</span><strong>− ${rupiah(order.discount)}</strong></div><div class="total-row grand"><span>Total</span><strong>${rupiah(order.total)}</strong></div></div></aside></div>`}
async function load(){if(!id||!accessToken){content.innerHTML='<div class="empty"><strong>Pelacakan belum tersedia untuk pesanan ini.</strong><br>Pesanan lama yang dibuat sebelum fitur pelacakan tidak memiliki token akses.<br><a href="orders.html">Kembali ke riwayat pesanan</a></div>';return}document.querySelector('#refresh').disabled=true;try{const response=await fetch(`/api/track/${encodeURIComponent(id)}?token=${encodeURIComponent(accessToken)}`),data=await response.json();if(!response.ok)throw new Error(data.error||'Status belum dapat dimuat');render(data)}catch(error){content.innerHTML=`<div class="empty"><strong>${escapeHtml(error.message)}</strong><br><a href="orders.html">Kembali ke riwayat pesanan</a></div>`}finally{document.querySelector('#refresh').disabled=false}}
document.querySelector('#refresh').addEventListener('click',load);load();
